package com.example.finance;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.example.finance.common.*;
import com.example.finance.student.StudentFinanceService;
import com.example.finance.tuition.*;
import com.example.finance.payment.*;
import com.example.finance.ledger.*;
import com.example.finance.security.*;
import jakarta.persistence.EntityManager;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:student-finance;MODE=MySQL;DB_CLOSE_DELAY=-1") @Transactional
class StudentFinanceTest {
 @Test void malformedPriceBreakdownRequiresReview(){tuition.setDiscountAmount(new BigDecimal("10"));em.flush();assertEquals("INVALID_AMOUNT",service.detail(tuition.getId()).tuition().reviewCode());assertNull(service.summary().outstanding());}
 @Test void correctionLinkedToAnotherTuitionIsNotExposedAsOwnHistory(){var p=payment(tuition,"100",Payment.Status.PAID);tuition.setPaidAmount(new BigDecimal("100"));var foreign=bill(201L,20L,22L,"2000");var c=new PaymentCorrection();c.setPaymentId(p.getId());c.setTuitionId(foreign.getId());c.setBranchId(3L);c.setType(PaymentCorrection.Type.REFUND);c.setAmount(BigDecimal.TEN);c.setReason("PRIVATE OTHER TUITION");c.setRequestKey(UUID.randomUUID().toString());c.setExpectedVersion(0L);c.setRecordedBy(1L);c.setRecordedByName("PRIVATE ACTOR");em.persist(c);em.flush();assertEquals("REVIEW_REQUIRED",service.receipt(p.getId()).receipt().state());assertTrue(service.receipt(p.getId()).corrections().isEmpty());assertFalse(service.summary().coverageComplete());}
 @Autowired StudentFinanceService service; @Autowired EntityManager em; @MockitoBean RemoteApi remote; Tuition tuition;
 void actor(Role role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(101L,11L,3L,role,"student"),null,List.of()));}
 StudentFinanceService.Registration registration(long id,long root,long cls){return new StudentFinanceService.Registration(id,root,cls,"Class "+cls,7L,"English",3L);}
 @BeforeEach void setup(){actor(Role.STUDENT);when(remote.get(anyString(),eq(StudentFinanceService.Scopes.class))).thenReturn(new StudentFinanceService.Scopes(11L,List.of(registration(101,101,9),registration(102,101,10))));tuition=bill(101L,9L,11L,"1000");}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 Tuition bill(Long enrollment,Long cls,Long student,String amount){var t=new Tuition();t.setEnrollmentId(enrollment);t.setStudentId(student);t.setClassId(cls);t.setBranchId(3L);t.setOriginalAmount(new BigDecimal(amount));t.setAmount(new BigDecimal(amount));t.setDueDate(LocalDate.now(BusinessTime.ZONE).plusDays(1));em.persist(t);em.flush();return t;}
 Payment payment(Tuition t,String amount,Payment.Status status){var p=new Payment();p.setTuitionId(t.getId());p.setBranchId(3L);p.setAmount(new BigDecimal(amount));p.setPaymentMethod(Payment.PaymentMethod.CASH);p.setStatus(status);p.setNote("PRIVATE NOTE");p.setReferenceCode("PRIVATE REFERENCE");em.persist(p);em.flush();return p;}
 void correction(Payment p,String amount,PaymentCorrection.Type type){var c=new PaymentCorrection();c.setPaymentId(p.getId());c.setTuitionId(p.getTuitionId());c.setBranchId(3L);c.setType(type);c.setAmount(new BigDecimal(amount));c.setReason("PRIVATE REASON");c.setRecordedBy(1L);c.setRecordedByName("PRIVATE ACTOR");c.setRequestKey(UUID.randomUUID().toString());c.setExpectedVersion(0L);em.persist(c);em.flush();}
 @Test void transferredRegistrationsShareExactlyOneBill(){var a=service.list(0,20,null,null,101L);var b=service.list(0,20,null,null,102L);assertEquals(1,a.totalElements());assertEquals(a.content().getFirst().id(),b.content().getFirst().id());assertEquals(List.of(101L,102L),a.content().getFirst().enrollmentIds());assertEquals("1000.00",service.summary().outstanding());}
 @Test void otherStudentCannotReadTuitionOrReceipt(){var foreign=bill(201L,20L,22L,"9000");var p=payment(foreign,"10",Payment.Status.PAID);assertEquals(1,service.list(0,20,null,null,null).totalElements());assertThrows(ApiException.class,()->service.detail(foreign.getId()));assertThrows(ApiException.class,()->service.receipt(p.getId()));assertThrows(ApiException.class,()->service.receipts(foreign.getId(),0,20));assertThrows(ApiException.class,()->service.list(0,20,null,null,201L));}
 @Test void voidKeepsReceiptHistoryButRemovesItsNet(){var p=payment(tuition,"200",Payment.Status.PAID);tuition.setPaidAmount(new BigDecimal("200"));em.flush();assertEquals("PARTIAL",service.detail(tuition.getId()).tuition().status());correction(p,"200",PaymentCorrection.Type.VOID);tuition.setPaidAmount(BigDecimal.ZERO);em.flush();assertEquals("UNPAID",service.detail(tuition.getId()).tuition().status());assertEquals("VOIDED",service.receipt(p.getId()).receipt().state());assertEquals("0.00",service.receipt(p.getId()).receipt().netAmount());assertEquals(1,service.receipts(null,0,20).totalElements());}
 @Test void partialRefundAndFullRefundUseCorrectionLedger(){var p=payment(tuition,"1000",Payment.Status.PAID);tuition.setAmount(new BigDecimal("600"));tuition.setDiscountAmount(new BigDecimal("400"));tuition.setPaidAmount(new BigDecimal("600"));correction(p,"400",PaymentCorrection.Type.REFUND);assertEquals("600.00",service.detail(tuition.getId()).tuition().netPaid());assertEquals("PARTIALLY_REFUNDED",service.receipt(p.getId()).receipt().state());correction(p,"600",PaymentCorrection.Type.REFUND);tuition.setAmount(BigDecimal.ZERO);tuition.setDiscountAmount(new BigDecimal("1000"));tuition.setPaidAmount(BigDecimal.ZERO);em.flush();assertEquals("REFUNDED",service.receipt(p.getId()).receipt().state());assertEquals("0.00",service.receipt(p.getId()).receipt().netAmount());}
 @Test void creditIsSeparateFromOutstanding(){payment(tuition,"1000",Payment.Status.PAID);tuition.setAmount(new BigDecimal("700"));tuition.setDiscountAmount(new BigDecimal("300"));tuition.setPaidAmount(new BigDecimal("1000"));em.flush();var v=service.detail(tuition.getId()).tuition();assertEquals("0.00",v.outstanding());assertEquals("300.00",v.credit());assertEquals("PAID",v.status());}
 @Test void cachedPaidMismatchAndLegacyReceiptNeverBecomeConfirmedBalance(){tuition.setPaidAmount(BigDecimal.ONE);em.flush();assertEquals("LEDGER_MISMATCH",service.detail(tuition.getId()).tuition().reviewCode());assertNull(service.summary().outstanding());tuition.setPaidAmount(BigDecimal.ZERO);var p=payment(tuition,"10",Payment.Status.REFUNDED);assertEquals("REVIEW_REQUIRED",service.receipt(p.getId()).receipt().state());assertNull(service.receipt(p.getId()).receipt().netAmount());assertFalse(service.summary().coverageComplete());}
 @Test void unlinkedAndChildDuplicateDoNotAddDebtTwice(){bill(null,9L,11L,"200");bill(102L,10L,11L,"1000");var s=service.summary();assertEquals(2,s.reviewCount());assertFalse(s.coverageComplete());assertNull(s.totalAmount());assertEquals(1,service.list(0,20,null,null,102L).totalElements());}
 @Test void cancelledExcludedFromActiveTotalsWhileReceiptsRemain(){tuition.setStatus(Tuition.Status.CANCELLED);payment(tuition,"1000",Payment.Status.PAID);tuition.setPaidAmount(new BigDecimal("1000"));em.flush();assertEquals("CANCELLED",service.detail(tuition.getId()).tuition().status());assertEquals("0.00",service.summary().totalAmount());assertEquals("0.00",service.summary().netPaid());assertEquals(1,service.summary().cancelledCount());assertEquals(1,service.receipts(null,0,20).totalElements());}
 @Test void missingBillingRootDoesNotProduceFakeZeroGrandTotal(){when(remote.get(anyString(),eq(StudentFinanceService.Scopes.class))).thenReturn(new StudentFinanceService.Scopes(11L,List.of(registration(101,101,9),registration(201,201,20))));assertEquals(1,service.summary().pendingBillingRoots());assertNull(service.summary().outstanding());}
 @Test void decimalPrecisionAndPaginationAreExact(){tuition.setAmount(new BigDecimal("9999999999999.99"));tuition.setOriginalAmount(tuition.getAmount());em.flush();assertEquals("9999999999999.99",service.summary().totalAmount());assertThrows(ApiException.class,()->service.list(Integer.MAX_VALUE,100,null,null,null));assertThrows(ApiException.class,()->service.receipts(null,0,101));assertThrows(ApiException.class,()->service.list(0,20,"UNKNOWN",null,null));}
 @Test void overdueStatusAndSummaryNotCalculatedFromOnePage(){tuition.setDueDate(LocalDate.now(BusinessTime.ZONE).minusDays(1));em.flush();assertEquals("OVERDUE",service.list(0,1,null,null,null).content().getFirst().status());assertEquals(1,service.summary().overdueCount());assertEquals(0,service.list(0,1,"PAID",null,null).totalElements());assertEquals("1000.00",service.summary().outstanding());}
 @Test void roleAndDependencyErrorsFailClosed(){actor(Role.ADMIN);assertThrows(ApiException.class,()->service.summary());actor(Role.STUDENT);when(remote.get(anyString(),eq(StudentFinanceService.Scopes.class))).thenThrow(new ApiException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"offline"));assertThrows(ApiException.class,()->service.summary());}
 @Test void publicReceiptProjectionDoesNotExposeOperationalNotes(){var p=payment(tuition,"200",Payment.Status.PAID);var r=service.receipt(p.getId());assertFalse(r.toString().contains("PRIVATE"));assertFalse(Arrays.stream(r.receipt().getClass().getRecordComponents()).anyMatch(c->Set.of("referenceCode","note","recordedBy","recordedByName").contains(c.getName())));}
}
